import React, { useState, memo } from 'react';
import TabNav, { TabKey } from '../components/TabNav';

type Props = {
  active: TabKey;
  onChange: (key: TabKey) => void;
  brandName?: string;
  tagline?: string;
  phone?: string;   // в формате +33765551111
  email?: string;   // contact@plus-propre.fr
};

const Header: React.FC<Props> = memo(function Header({
  active,
  onChange,
  brandName = '+Propre',
  tagline = 'Service de nettoyage & d’entretien',
  phone = '+33765551111',
  email = 'contact@plus-propre.fr',
}) {
  const [open, setOpen] = useState(false);

  const phonePretty = phone
    .replace('+33', '0')
    .replace(/(\d{2})(?=\d)/g, '$1 ')
    .trim();

  return (
    <>
      {/* Ссылка пропуска к контенту для доступности */}
      <a className="skip-link" href="#main">Aller au contenu</a>

      <header className="header header--sticky" role="banner">
        <nav
          className="container nav"
          role="navigation"
          aria-label="Navigation principale"
        >
          <div className="brand">
            <a href="#accueil" className="brand__link" onClick={() => onChange('accueil')}>
              <span className="logo" aria-hidden="true">+</span>
              <span className="brand-name">{brandName}</span>
            </a>
            <span className="badge" title="Couverture Île-de-France">{tagline}</span>
          </div>

          {/* Кнопка-бургер для мобильных */}
          <button
            className="nav-toggle"
            aria-label={open ? 'Fermer le menu' : 'Ouvrir le menu'}
            aria-expanded={open}
            aria-controls="site-tabs"
            onClick={() => setOpen(v => !v)}
          >
            <span aria-hidden="true">☰</span>
          </button>

          <div className={`nav-right ${open ? 'is-open' : ''}`}>
            <TabNav active={active} onChange={(k) => { setOpen(false); onChange(k); }} />
            <div className="quick-info">
              <a href={`tel:${phone}`} aria-label={`Téléphoner ${phonePretty}`}>📞 {phonePretty}</a>
              <span className="dot" aria-hidden="true">•</span>
              <a href={`mailto:${email}`}>✉️ {email}</a>
            </div>
          </div>
        </nav>
      </header>
    </>
  );
});

export default Header;
